mapper.select:
SELECT COALESCE (pf.num,0) as num, mc.market_tenant, mc.market_name FROM market_config mc left join ( select market_tenant,market_name,sum(num) as num from property_filing
STATUS = 'EXPIRE'
and market_tenant = #{query.marketTenant}
and create_time >= #{query.period.begin} and create_time < #{query.period.end}
and property_type = #{type}
group by market_tenant order by num asc ) pf on mc.market_tenant = pf.market_tenant
mc.status = true

SELECT COALESCE (pf.num,0) as num, mc.market_tenant, mc.market_name FROM market_config mc left join ( select market_tenant,market_name,sum(num) as num from property_filing
STATUS = 'EXPIRE'
and market_tenant = #{query.marketTenant}
and create_time >= #{query.period.begin} and create_time < #{query.period.end}
and property_sub_type = #{query.subTypeCode}
and property_type = #{type}
group by market_tenant order by num asc ) pf on mc.market_tenant = pf.market_tenant
mc.status = true
ORDER BY pf.num desc

SELECT pf.status, COUNT(1) count FROM property_filing pf left join market_config mc on mc.market_tenant = pf.market_tenant
mc.status = true
AND pf.market_tenant IN
#{id}
AND pf.create_time BETWEEN #{query.createdPeriod.begin} AND #{query.createdPeriod.end}
AND pf.property_type IN
#{type}
GROUP BY pf.status

select
pf.*
from
property_filing pf
left join market_config mc on mc.market_tenant = pf.market_tenant

    mc.status = true

        and pf.create_time >= #{query.period.begin} and pf.create_time <
        #{query.period.end}


        and pf.market_tenant = #{query.marketTenant}


        and pf.property_type = #{query.type}


        and pf.property_sub_type = #{query.subType}


        and pf.status = #{query.state}


        and pf.put_in_time >= #{query.putInDate.begin} and pf.put_in_time <
        #{query.putInDate.end}


        and pf.status = 'EXPIRE'


order by pf.create_time desc

select pf.* from property_filing pf left join market_config mc on mc.market_tenant = pf.market_tenant
mc.status = true
and pf.create_time >= #{query.period.begin} and pf.create_time < #{query.period.end}
and pf.market_tenant = #{query.marketTenant}
and pf.property_type = #{query.typeCode}
and pf.status = 'EXPIRE'

select
pf.*
from
property_filing pf
left join market_config mc on mc.market_tenant = pf.market_tenant

    mc.status = true

        and pf.create_time >= #{query.period.begin} and pf.create_time <
        #{query.period.end}


        and pf.market_tenant = #{query.marketTenant}


        and pf.property_type = #{query.propertyCategory}


        and pf.status = #{query.status}


        and pf.status = 'EXPIRE'

select pf.property_type AS groupKey, COUNT(pf.id) AS count from property_filing pf left join market_config mc on mc.market_tenant = pf.market_tenant
mc.status = true
and pf.create_time >= #{query.createdPeriod.begin} and pf.create_time < #{query.createdPeriod.end}
and pf.market_tenant in
#{marketTenant}
group by pf.property_type

select pf.market_tenant AS marketTenant, pf.market_name AS marketName, COUNT(pf.id) AS count from property_filing pf left join market_config mc on mc.market_tenant = pf.market_tenant
mc.status = true
and pf.create_time >= #{query.createdPeriod.begin} and pf.create_time < #{query.createdPeriod.end}
and pf.property_sub_type in
#{type}
and pf.market_tenant in
#{marketTenant}
group by pf.market_name
